-- Restaurar wallpaper salvo (swaybg) ao iniciar
hl.on("hyprland.start", function ()
    local wp = os.getenv("HOME") .. "/.config/hypr/current-wallpaper"
    local f = io.open(wp, "r")
    if f then
        local path = f:read("*l")
        f:close()
        if path and #path > 0 then
            hl.exec_cmd("pkill -x swaybg 2>/dev/null; swaybg -i '" .. path .. "' &")
        end
    end
end)

-- Notificações (dunst) e aviso de música (MPRIS/playerctl)
hl.on("hyprland.start", function ()
    hl.exec_cmd("pkill -x dunst 2>/dev/null; dunst &")
    hl.exec_cmd("pkill -f 'music-notify.sh' 2>/dev/null; ~/.config/hypr/scripts/music-notify.sh &")
end)

-- Waybar
hl.on("hyprland.start", function ()
    hl.exec_cmd("pkill -x waybar 2>/dev/null; sleep 0.2; env LANG=pt_BR.UTF-8 LC_TIME=pt_BR.UTF-8 LC_ALL=pt_BR.UTF-8 waybar -c ~/.config/waybar/config.jsonc -s ~/.config/waybar/style.css &")
end)

-- Histórico da área de transferência (cliphist)
hl.on("hyprland.start", function ()
    hl.exec_cmd("wl-paste --type text --watch cliphist store &")
    hl.exec_cmd("wl-paste --type image --watch cliphist store &")
end)


